import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Geometry for a simple rectangular card (size can be adjusted via scaling later)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  // Load texture asynchronously; assign when ready
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  mesh.userData.handlers = {};

  // Hover lift (rise‑in) effect
  mesh.userData.handlers.hover = () => {
    // Kill any existing hover timeline
    if (mesh.userData._hoverTl) mesh.userData._hoverTl.kill();

    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: '+=0.15',
      duration: 0.7,
      ease: 'power3.out',
    });
    mesh.userData._hoverTl = tl;
  };

  // Click emit
  mesh.userData.handlers.click = () => {
    ctx.emit('hub-collection.select');
  };

  // Cleanup resources and timelines
  mesh.userData.cleanup = () => {
    if (mesh.userData._hoverTl) mesh.userData._hoverTl.kill();
    material.dispose();
    geometry.dispose();
    if (loadedTexture && loadedTexture.dispose) loadedTexture.dispose();
  };

  return mesh;
}
